using System;
using System.IO;
using System.Net;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using System.Collections.Concurrent;

namespace SecureProxy
{
    public class EncryptedStorageProvider
    {
        private readonly byte[] _masterKey;
        private readonly string _storagePath;

        public EncryptedStorageProvider(byte[] masterKey, string storagePath)
        {
            _masterKey = masterKey;
            _storagePath = storagePath;
        }

        public byte[] DeriveSessionKey(string sessionId, byte[] context)
        {
            using (var hmac = new HMACSHA256(_masterKey))
            {
                var input = Encoding.UTF8.GetBytes(sessionId);
                return hmac.ComputeHash(input);
            }
        }

        private byte[] GenerateNonce()
        {
            var nonce = new byte[12];
            using (var rng = RandomNumberGenerator.Create())
            {
                rng.GetBytes(nonce);
            }
            return nonce;
        }

        public byte[] Encrypt(byte[] plaintext, string sessionId)
        {
            var key = DeriveSessionKey(sessionId, null);
            var nonce = GenerateNonce();
            var ciphertext = new byte[plaintext.Length];
            var tag = new byte[16];

            using (var aes = new AesGcm(key))
            {
                aes.Encrypt(nonce, plaintext, ciphertext, tag);
            }

            var result = new byte[nonce.Length + ciphertext.Length + tag.Length];
            Buffer.BlockCopy(nonce, 0, result, 0, nonce.Length);
            Buffer.BlockCopy(ciphertext, 0, result, nonce.Length, ciphertext.Length);
            Buffer.BlockCopy(tag, 0, result, nonce.Length + ciphertext.Length, tag.Length);
            return result;
        }

        public byte[] Decrypt(byte[] encryptedData, string sessionId)
        {
            var key = DeriveSessionKey(sessionId, null);
            var nonce = new byte[12];
            Buffer.BlockCopy(encryptedData, 0, nonce, 0, 12);
            var ciphertext = new byte[encryptedData.Length - 28];
            Buffer.BlockCopy(encryptedData, 12, ciphertext, 0, ciphertext.Length);
            var tag = new byte[16];
            Buffer.BlockCopy(encryptedData, encryptedData.Length - 16, tag, 0, 16);

            var plaintext = new byte[ciphertext.Length];
            using (var aes = new AesGcm(key))
            {
                aes.Decrypt(nonce, ciphertext, tag, plaintext);
            }
            return plaintext;
        }
    }

    public class ProxySession
    {
        public string SessionId { get; set; }
        public DateTime CreatedAt { get; set; }
        public IPEndPoint ClientEndpoint { get; set; }
        public int MessageCount { get; set; }
    }

    public class NetworkProxy
    {
        private readonly EncryptedStorageProvider _storage;
        private readonly ConcurrentDictionary<string, ProxySession> _sessions;
        private readonly TcpListener _listener;
        private readonly int _port;

        public NetworkProxy(int port, byte[] masterKey, string storagePath)
        {
            _port = port;
            _storage = new EncryptedStorageProvider(masterKey, storagePath);
            _sessions = new ConcurrentDictionary<string, ProxySession>();
            _listener = new TcpListener(IPAddress.Loopback, port);
        }

        public async Task StartAsync()
        {
            _listener.Start();
            while (true)
            {
                var client = await _listener.AcceptTcpClientAsync();
                _ = HandleClientAsync(client);
            }
        }

        private async Task HandleClientAsync(TcpClient client)
        {
            var sessionId = GenerateSessionId(client);
            var session = _sessions.GetOrAdd(sessionId, id => new ProxySession
            {
                SessionId = id,
                CreatedAt = DateTime.UtcNow,
                ClientEndpoint = (IPEndPoint)client.Client.RemoteEndPoint,
                MessageCount = 0
            });

            using (var stream = client.GetStream())
            {
                var buffer = new byte[4096];
                int bytesRead;
                while ((bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length)) > 0)
                {
                    var data = new byte[bytesRead];
                    Buffer.BlockCopy(buffer, 0, data, 0, bytesRead);

                    session.MessageCount++;
                    var encrypted = _storage.Encrypt(data, sessionId);
                    await StoreEncryptedPayload(sessionId, session.MessageCount, encrypted);

                    var response = ProcessAndForward(data);
                    var encResponse = _storage.Encrypt(response, sessionId);
                    await StoreEncryptedPayload(sessionId + "_resp", session.MessageCount, encResponse);

                    await stream.WriteAsync(response, 0, response.Length);
                }
            }
        }

        private string GenerateSessionId(TcpClient client)
        {
            var endpoint = (IPEndPoint)client.Client.RemoteEndPoint;
            var raw = $"{endpoint.Address}:{endpoint.Port}:{DateTime.UtcNow.Ticks}";
            using (var sha = SHA256.Create())
            {
                var hash = sha.ComputeHash(Encoding.UTF8.GetBytes(raw));
                // Use URL-safe base64 without path-separator characters to avoid
                // filename/path injection when the session id is used in file names.
                var safe = Convert.ToBase64String(hash)
                    .Replace('+', '-')
                    .Replace('/', '_')
                    .Replace("=", string.Empty);
                return safe.Substring(0, 16);
            }
        }

        private byte[] ProcessAndForward(byte[] data)
        {
            return Encoding.UTF8.GetBytes($"ACK:{data.Length}");
        }

        private static string SanitizeComponent(string component)
        {
            var sb = new StringBuilder(component.Length);
            foreach (var c in component)
            {
                if (char.IsLetterOrDigit(c) || c == '_' || c == '-')
                {
                    sb.Append(c);
                }
                else
                {
                    sb.Append('_');
                }
            }
            return sb.Length == 0 ? "_" : sb.ToString();
        }

        private async Task StoreEncryptedPayload(string sessionId, int seqNum, byte[] payload)
        {
            var safeSession = SanitizeComponent(sessionId);
            var filename = $"{safeSession}_{seqNum}.enc";
            var storeRoot = Path.GetFullPath(Path.Combine(Path.GetTempPath(), "proxy_store"));
            var path = Path.GetFullPath(Path.Combine(storeRoot, filename));

            // Ensure the resolved path stays within the intended storage root.
            var rootWithSep = storeRoot.EndsWith(Path.DirectorySeparatorChar.ToString())
                ? storeRoot
                : storeRoot + Path.DirectorySeparatorChar;
            if (!path.StartsWith(rootWithSep, StringComparison.Ordinal))
            {
                throw new UnauthorizedAccessException("Invalid storage path.");
            }

            Directory.CreateDirectory(storeRoot);
            await File.WriteAllBytesAsync(path, payload);
        }
    }

    class Program
    {
        static async Task Main(string[] args)
        {
            var masterKey = new byte[32];
            using (var rng = RandomNumberGenerator.Create())
            {
                rng.GetBytes(masterKey);
            }

            var proxy = new NetworkProxy(8443, masterKey, "/var/proxy/store");
            await proxy.StartAsync();
        }
    }
}
